ALTER TABLE diagnostic_packs ADD COLUMN IF NOT EXISTS active_version INT UNSIGNED NULL;
CREATE TABLE IF NOT EXISTS diagnostic_pack_versions (organization_id VARCHAR(40) NOT NULL,pack_id VARCHAR(100) NOT NULL,methodology_version VARCHAR(32) NOT NULL,schema_version VARCHAR(40) NOT NULL,status ENUM('DRAFT','VALIDATING','READY','PUBLISHED','ARCHIVED') NOT NULL,description TEXT NOT NULL,created_by VARCHAR(100) NOT NULL,based_on_version VARCHAR(32) NULL,content_hash CHAR(64) NOT NULL,published_at DATETIME(6) NULL,created_at DATETIME(6) NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(organization_id,pack_id,methodology_version),CONSTRAINT fk_studio_pack_org FOREIGN KEY(organization_id) REFERENCES cos_organizations(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS diagnostic_methodology_entities (organization_id VARCHAR(40) NOT NULL,pack_id VARCHAR(100) NOT NULL,methodology_version VARCHAR(32) NOT NULL,entity_type ENUM('AREA','CRITERION','FACT','METRIC','QUESTION','EVIDENCE_REQUIREMENT','RULE','DEPENDENCY','RECOMMENDATION','BENCHMARK','SCORING') NOT NULL,entity_id VARCHAR(160) NOT NULL,position INT NOT NULL DEFAULT 0,enabled TINYINT(1) NOT NULL DEFAULT 1,payload_json JSON NOT NULL,updated_at DATETIME(6) NOT NULL,PRIMARY KEY(organization_id,pack_id,methodology_version,entity_type,entity_id),CONSTRAINT fk_studio_entity_version FOREIGN KEY(organization_id,pack_id,methodology_version) REFERENCES diagnostic_pack_versions(organization_id,pack_id,methodology_version) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS diagnostic_test_scenarios (organization_id VARCHAR(40) NOT NULL,pack_id VARCHAR(100) NOT NULL,methodology_version VARCHAR(32) NOT NULL,scenario_id VARCHAR(100) NOT NULL,name VARCHAR(220) NOT NULL,input_json JSON NOT NULL,expected_json JSON NOT NULL,created_at DATETIME(6) NOT NULL,PRIMARY KEY(organization_id,pack_id,methodology_version,scenario_id),CONSTRAINT fk_studio_scenario_version FOREIGN KEY(organization_id,pack_id,methodology_version) REFERENCES diagnostic_pack_versions(organization_id,pack_id,methodology_version) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS diagnostic_test_results (organization_id VARCHAR(40) NOT NULL,run_id CHAR(32) NOT NULL,pack_id VARCHAR(100) NOT NULL,methodology_version VARCHAR(32) NOT NULL,scenario_id VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL,result_json JSON NOT NULL,created_at DATETIME(6) NOT NULL,PRIMARY KEY(organization_id,run_id,scenario_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS diagnostic_methodology_audit (organization_id VARCHAR(40) NOT NULL,audit_id CHAR(32) NOT NULL,pack_id VARCHAR(100) NOT NULL,methodology_version VARCHAR(32) NOT NULL,user_id VARCHAR(100) NOT NULL,entity_type VARCHAR(40) NOT NULL,entity_id VARCHAR(160) NOT NULL,old_value_json JSON NULL,new_value_json JSON NULL,created_at DATETIME(6) NOT NULL,PRIMARY KEY(organization_id,audit_id),KEY idx_methodology_audit(organization_id,pack_id,methodology_version,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
